'use strict';

// Innocent package: `unusedHelper` is a top-level FunctionDeclaration whose
// only references are its export site — without the hazard elsewhere in the
// traced set it is proven-unreachable and gets stubbed (verified by control
// run). The hazard must force it to "unknown" instead.
function used(s) {
  return s.toUpperCase();
}

function unusedHelper(s) {
  return s.split('').reverse().join('');
}

exports.used = used;
exports.unusedHelper = unusedHelper;
